    static func date(of term: String, year: Int) -> Date? {
        guard let key = table[year]?[term] else { return nil }
        return HolidayService.date(fromKey: key)
    }

    /// 某天正好是哪个节气（不是节气日返回 nil）
    static func term(on date: Date) -> String? {
        let key = HolidayService.key(for: date)
        let year = Calendar(identifier: .gregorian).component(.year, from: date)
        return table[year]?.first(where: { $0.value == key })?.key
    }

    /// 最近一个已过的节气（日期条副文案用）
    static func currentTerm(on date: Date) -> String? {
        let y = Calendar(identifier: .gregorian).component(.year, from: date)
        var all: [(String, Date)] = []
        for year in [y - 1, y] {
            for (name, key) in table[year] ?? [:] {
                if let d = HolidayService.date(fromKey: key) { all.append((name, d)) }
            }
        }
        return all.sorted { $0.1 < $1.1 }.last(where: { $0.1 <= date })?.0
    }
}
